import pytest

from numeric import integer_sqrt


def test_integer_sqrt_negative():
    with pytest.raises(ValueError, match="n must be non-negative"):
        integer_sqrt(-1)


def test_integer_sqrt_zero():
    assert integer_sqrt(0) == 0


def test_integer_sqrt_one():
    assert integer_sqrt(1) == 1


def test_integer_sqrt_small_positive():
    assert integer_sqrt(2) == 1
    assert integer_sqrt(3) == 1
    assert integer_sqrt(4) == 2


def test_integer_sqrt_large_perfect_square():
    assert integer_sqrt(1000000) == 1000


def test_integer_sqrt_large_non_perfect_square():
    assert integer_sqrt(1000001) == 1000


def test_integer_sqrt_boundary_high():
    assert integer_sqrt(2147483647) == 46340  # sqrt(2^31-1) ≈ 46340.95

import pytest

from numeric import integer_sqrt


def test_integer_sqrt_exact_square_root():
    """Test that perfect squares return exact integer roots."""
    for i in range(1, 11):
        n = i * i
        assert integer_sqrt(n) == i


def test_integer_sqrt_non_square_root():
    """Test that non-perfect squares return floor of sqrt."""
    for i in range(1, 10):
        n = i * i + 1
        assert integer_sqrt(n) == i


def test_integer_sqrt_large_values():
    """Test integer_sqrt with large inputs (but not too large for int)."""
    assert integer_sqrt(2**64 - 1) == 2**32 - 1


def test_integer_sqrt_edge_case_one():
    """Test edge case: n = 2, which is handled by early return."""
    assert integer_sqrt(2) == 1


def test_integer_sqrt_edge_case_zero():
    """Test edge case: n = 0, which is handled by early return."""
    assert integer_sqrt(0) == 0


def test_integer_sqrt_negative_raises():
    """Test that negative inputs raise ValueError."""
    with pytest.raises(ValueError, match="n must be non-negative"):
        integer_sqrt(-100)

