import pytest

from numeric import moving_average


def test_moving_average_empty():
    assert moving_average([], 1) == []


def test_moving_average_window_1():
    assert moving_average([1, 2, 3], 1) == [1, 2, 3]


def test_moving_average_window_equal_length():
    assert moving_average([1, 2, 3], 3) == [2.0]


def test_moving_average_window_too_small():
    with pytest.raises(ValueError, match="window must be >= 1"):
        moving_average([1, 2, 3], 0)


