    with pytest.raises(ValueError, match="window larger than data"):
        moving_average([1, 2], 3)


def test_moving_average_float_values():
    assert moving_average([1.5, 2.5, 3.5], 2) == [2.0, 3.0]


def test_moving_average_single_element():
    assert moving_average([42], 1) == [42]

